#include <stdio.h>
int main() {
    int arr[5] = {10, 20, 30, 40, 50};
    int *p = arr + 2;
    printf("%d", *p + *(p + 1));
    return 0;
}

class Parent {
    int compute(int num) {
        if (num <= 1) return num;
        return compute(num - 1) + compute(num - 2);
    }
}
public class Main {
    public static void main(String[] args) {
        Parent p = new Parent();
        System.out.print(p.compute(6));
    }
}

#include <stdio.h>
int main() {
    int sum = 0;
    for(int i = 1; i <= 10; i++) {
        if(i % 3 == 0) sum += i;
    }
    printf("%d", sum);
    return 0;
}

class A {
    int a = 10;
    int get() { return a; }
}
class B extends A {
    int a = 20;
    int get() { return a + 5; }
}
public class Main {
    public static void main(String[] args) {
        A obj = new B();
        System.out.print(obj.get());
    }
}

